    (13285, '_pg_index_position', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 's', 'u', 2, 0, 23, '26 21', None, None, None, None, '', None, 'BEGIN ATOMIC\n SELECT (ss.a).n AS n\n    FROM ( SELECT information_schema._pg_expandarray(pg_index.indkey) AS a\n            FROM pg_index\n           WHERE (pg_index.indexrelid = $1)) ss\n   WHERE ((ss.a).x = $2);\nEND'),
    (13286, '_pg_truetypid', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 26, '75 71', None, None, None, None, '', None, 'RETURN CASE WHEN (($2).typtype = \'d\'::"char") THEN ($2).typbasetype ELSE ($1).atttypid END'),
    (13287, '_pg_truetypmod', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '75 71', None, None, None, None, '', None, 'RETURN CASE WHEN (($2).typtype = \'d\'::"char") THEN ($2).typtypmod ELSE ($1).atttypmod END'),
    (13288, '_pg_char_max_length', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, "RETURN CASE WHEN (typmod = '-1'::integer) THEN NULL::integer WHEN (typid = ANY (ARRAY[(1042)::oid, (1043)::oid])) THEN (typmod - 4) WHEN (typid = ANY (ARRAY[(1560)::oid, (1562)::oid])) THEN typmod ELSE NULL::integer END"),
    (13289, '_pg_char_octet_length', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, "RETURN CASE WHEN (typid = ANY (ARRAY[(25)::oid, (1042)::oid, (1043)::oid])) THEN CASE WHEN (typmod = '-1'::integer) THEN (((2)::double precision ^ (30)::double precision))::integer ELSE (information_schema._pg_char_max_length(typid, typmod) * pg_encoding_max_length((SELECT pg_database.encoding FROM pg_database WHERE (pg_database.datname = current_database())))) END ELSE NULL::integer END"),
    (13291, '_pg_numeric_precision', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, "RETURN CASE typid WHEN 21 THEN 16 WHEN 23 THEN 32 WHEN 20 THEN 64 WHEN 1700 THEN CASE WHEN (typmod = '-1'::integer) THEN NULL::integer ELSE (((typmod - 4) >> 16) & 65535) END WHEN 700 THEN 24 WHEN 701 THEN 53 ELSE NULL::integer END"),
    (13292, '_pg_numeric_precision_radix', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, 'RETURN CASE WHEN (typid = ANY (ARRAY[(21)::oid, (23)::oid, (20)::oid, (700)::oid, (701)::oid])) THEN 2 WHEN (typid = (1700)::oid) THEN 10 ELSE NULL::integer END'),
    (13293, '_pg_numeric_scale', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, "RETURN CASE WHEN (typid = ANY (ARRAY[(21)::oid, (23)::oid, (20)::oid])) THEN 0 WHEN (typid = (1700)::oid) THEN CASE WHEN (typmod = '-1'::integer) THEN NULL::integer ELSE ((typmod - 4) & 65535) END ELSE NULL::integer END"),
    (13294, '_pg_datetime_precision', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 23, '26 23', None, None, ('typid', 'typmod'), None, '', None, 'RETURN CASE WHEN (typid = (1082)::oid) THEN 0 WHEN (typid = ANY (ARRAY[(1083)::oid, (1114)::oid, (1184)::oid, (1266)::oid])) THEN CASE WHEN (typmod < 0) THEN 6 ELSE typmod END WHEN (typid = (1186)::oid) THEN CASE WHEN ((typmod < 0) OR ((typmod & 65535) = 65535)) THEN 6 ELSE (typmod & 65535) END ELSE NULL::integer END'),
    (13295, '_pg_interval_type', 13283, 14, 100, 0, 0, 0, 'f', False, False, True, False, 'i', 's', 2, 0, 25, '26 23', None, None, ('typid', 'mod'), None, '', None, 'RETURN CASE WHEN (typid = (1186)::oid) THEN upper(SUBSTRING(format_type(typid, mod) SIMILAR \'interval[()0-9]* #"%#"\'::text ESCAPE \'#\'::text)) ELSE NULL::text END'),
